sections['index']=('Executive summary','Start with the source of the money, not a workaround.', '''<div class="callout"><strong>Best starting point — conditional, not a guaranteed cheapest route</strong><p>If the balance is documented after-tax employment income, compare a direct bank conversion/remittance with Wise’s eligible outbound salary service. If it is property, inheritance, original inbound funds or investments, use the corresponding documented route instead. An unexplained account balance cannot safely be treated as salary.</p></div><div class="stats"><div><b>18</b><span>Routes & variants assessed</span></div><div><b>10</b><span>Official-source records</span></div><div><b>Unknown</b><span>Your actual tax & net USD</span></div></div><h2>What matters most</h2>''')
summary=[['Tax is not the same as permission','US citizens are taxed on worldwide income. Moving funds is not the test used by the IRS worldwide-income rule; original income and any realized currency gain need separate treatment. No universal remittance-tax percentage has been established for this account.','world 988'],['The USD 50,000 claim needs care','PBOC Article 13 provides a documented lawful-income route for non-domestic individuals. HSBC’s quota wording and PBOC Article 9 are not identical. Do not treat a blog’s quota summary as a decision rule.','pbc hsbc'],['Reduce double taxation lawfully','Investigate creditable Chinese income taxes under the US foreign tax credit, subject to limitations. Taxes on income excluded under the foreign earned income exclusion cannot also generate a credit.','credit'],['Cheapest cannot be established yet','No account amount, source, bank quote, basis history, tax records or filing status was supplied. Compare eligible routes on identical CNY debit and actual net USD receipt, not an advertised headline rate. This is editorial methodology, not a provider quote.','wise hsbc'],['No action on your accounts','Research and publication only. No funds moved, tax return filed or bank contacted on your behalf. Provider identity verification and bank approvals cannot be completed from this repository.','wise hsbc']]

def table(headers, rows):
 return '<div class="table-wrap"><table><thead><tr>'+''.join('<th scope="col">'+esc(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in r)+'</tr>' for r in rows)+'</tbody></table></div>'
def sourced(headers, rows): return table(headers, [[esc(c) for c in r[:-1]]+[links(r[-1].split())] for r in rows])
sections['index']=(sections['index'][0],sections['index'][1],sections['index'][2]+sourced(['Finding','Meaning / analysis','Official sources'],summary)+'<p><a href="../index.html">Original research dashboard →</a> · <a href="../dossier/index.html">Verified dossier (35 routes, measured 0.42% spread) →</a> · The concurrent session’s original pages and findings are preserved separately. Their verification log remains in COORDINATION.md; this supplemental source audit covers the records listed here, not an independent re-audit of that edition.</p><h2>Decision sequence</h2><p>1. Establish ownership and origin → 2. Reconcile Chinese tax evidence and US reporting → 3. Select the matching lawful category → 4. Obtain executable bank/provider quotes → 5. Retain the complete audit trail.</p><p class="muted">This sequence is editorial synthesis. It is not personalized legal advice or a promise of approval, zero tax, or a fee waiver.</p>')
